entries[176087] = { ["name"] = "Juwelenschliffgeheimnisse von Draenor", ["text"] = "Wirken in 3.5 sek. 1 tag Abklingzeit\nTools: Juwelierswerkzeuge\nReagenzien:\nSchwarzfelserz (5)\nAbklingzeit wird täglich abgeschlossen.\nVerkäufer:\nCostan Hochwall\nGegenstand:\nJuwelierskunst von Draenor\nKosten:\n100\nZone:\nMondsturz\n\nVerkäufer:\nJuwelenkonstrukteur Harlaan\nGegenstand:\nJuwelierskunst von Draenor\nKosten:\n100\nZone:\nAshran\n\nJuwelenschliffgeheimnis von Draenor\nWird beim Aufheben gebunden\n\"Kann in Eurer Garnison im jeweiligen Handwerksgebäude oder in Ashran gegen Vorlagen eingetauscht werden.\"" }
entries[176089] = { ["name"] = "Lederverarbeitungsgeheimnisse von Draenor", ["text"] = "Wirken in 1.5 sek. 1 tag Abklingzeit\nReagenzien:\nRohes Tierleder (5)\nAbklingzeit wird täglich abgeschlossen.\nVerkäufer:\nAnders Kreuzstich\nGegenstand:\nLederverarbeitung von Draenor\nKosten:\n100\nZone:\nMondsturz\n\nVerkäufer:\nLeara Mondseide\nGegenstand:\nLederverarbeitung von Draenor\nKosten:\n100\nZone:\nAshran\n\nLederverarbeitungsgeheimnis von Draenor\nWird beim Aufheben gebunden\n\"Kann in Eurer Garnison im jeweiligen Handwerksgebäude oder in Ashran gegen Muster eingetauscht werden.\"" }
entries[176090] = { ["name"] = "Schmiedegeheimnisse von Draenor", ["text"] = "Wirken in 3.5 sek. 1 tag Abklingzeit\nTools: Schmiedehammer\nReagenzien:\nEchteisenerz (5)\nAbklingzeit wird täglich abgeschlossen.\nVerkäufer:\nAuria Erzträumer\nGegenstand:\nSchmiedekunst von Draenor\nKosten:\n100\nZone:\nMondsturz\n\nVerkäufer:\nRoyce Großbart\nGegenstand:\nSchmiedekunst von Draenor\nKosten:\n100\nZone:\nAshran\n\nSchmiedegeheimnis von Draenor\nWird beim Aufheben gebunden\n\"Kann in Eurer Garnison im jeweiligen Handwerksgebäude oder in Ashran gegen Pläne eingetauscht werden.\"" }
