entries[176313] = { ["name"] = "Inspirierende Schlachtstandarte", ["text"] = "Wirken in 2 sek.\nReagenzien:\nPrächtiges Fell (5)\nInspirierende Schlachtstandarte\nWird beim Aufheben gebunden\nEinzigartig (5)\nBenutzen: Stellt Eure Schlachtstandarte auf, um Eure Verbündeten zu inspirieren. Solang die Standarte steht, wird die maximale Gesundheit von Verbündeten innerhalb von 8 Metern um 30% erhöht.\n\nHält 1 Min. lang oder bis zu ihrer Zerstörung an. Kann nur in Außengebieten von Draenor verwendet werden. (1 Min Abklingzeit)\n35\n\"Eure Schlachtstandarte, bestickt mit den Farben der Allianz und handgefertigt vom Schneider Eurer Garnison.\"" }
entries[176314] = { ["name"] = "Furchterregende Schlachtstandarte", ["text"] = "Wirken in 2 sek.\nReagenzien:\nPrächtiges Fell (5)\nAllianz\nFurchterregende Schlachtstandarte\nWird beim Aufheben gebunden\nEinzigartig (5)\nBenutzen: Stellt Eure Schlachtstandarte auf, um Eure Gegner in Angst und Schrecken zu versetzen. Solange die Standarte steht, erleiden Gegner innerhalb von 8 Metern alle 3 Sek. 77204 Schaden.\n\nHält 1 Min. lang oder bis zu ihrer Zerstörung an. Kann nur in Außengebieten von Draenor verwendet werden. (1 Min Abklingzeit)\n35\n\"Eure Schlachtstandarte, geschmückt mit den Farben der Allianz und handgefertigt vom Schneider Eurer Garnison.\"\nHorde\nFurchterregende Schlachtstandarte\nWird beim Aufheben gebunden\nEinzigartig (5)\nBenutzen: Stellt Eure Schlachtstandarte auf, um Eure Gegner in Angst und Schrecken zu versetzen. Solang die Standarte steht, erleiden Gegner innerhalb von 8 Metern alle 3 Sek. 77204 Schaden.\n\nHält 1 Min. lang oder bis zu ihrer Zerstörung an. Kann nur in Außengebieten von Draenor verwendet werden. (1 Min Abklingzeit)\n35\n\"Eure Schlachtstandarte, geschmückt mit den Farben der Horde und handgefertigt vom Schneider Eurer Garnison.\"" }
entries[176315] = { ["name"] = "Inspirierende Schlachtstandarte", ["text"] = "Wirken in 2 sek.\nReagenzien:\nPrächtiges Fell (5)\nInspirierende Schlachtstandarte\nWird beim Aufheben gebunden\nEinzigartig (5)\nBenutzen: Stellt Eure Schlachtstandarte auf, um Eure Verbündeten zu inspirieren. Solang die Standarte steht, wird die maximale Gesundheit von Verbündeten innerhalb von 8 Metern um 30% erhöht.\n\nHält 1 Min. lang oder bis zu ihrer Zerstörung an. Kann nur in Außengebieten von Draenor verwendet werden. (1 Min Abklingzeit)\n35\n\"Eure Schlachtstandarte, geschmückt mit den Farben der Horde und handgefertigt vom Schneider Eurer Garnison.\"" }
entries[176316] = { ["name"] = "Furchterregende Schlachtstandarte", ["text"] = "Wirken in 2 sek.\nReagenzien:\nPrächtiges Fell (5)\nHorde\nFurchterregende Schlachtstandarte\nWird beim Aufheben gebunden\nEinzigartig (5)\nBenutzen: Stellt Eure Schlachtstandarte auf, um Eure Gegner in Angst und Schrecken zu versetzen. Solang die Standarte steht, erleiden Gegner innerhalb von 8 Metern alle 3 Sek. 77204 Schaden.\n\nHält 1 Min. lang oder bis zu ihrer Zerstörung an. Kann nur in Außengebieten von Draenor verwendet werden. (1 Min Abklingzeit)\n35\n\"Eure Schlachtstandarte, geschmückt mit den Farben der Horde und handgefertigt vom Schneider Eurer Garnison.\"\nAllianz\nFurchterregende Schlachtstandarte\nWird beim Aufheben gebunden\nEinzigartig (5)\nBenutzen: Stellt Eure Schlachtstandarte auf, um Eure Gegner in Angst und Schrecken zu versetzen. Solange die Standarte steht, erleiden Gegner innerhalb von 8 Metern alle 3 Sek. 77204 Schaden.\n\nHält 1 Min. lang oder bis zu ihrer Zerstörung an. Kann nur in Außengebieten von Draenor verwendet werden. (1 Min Abklingzeit)\n35\n\"Eure Schlachtstandarte, geschmückt mit den Farben der Allianz und handgefertigt vom Schneider Eurer Garnison.\"" }
